import { trace } from '@opentelemetry/api'

export async function fetchGithubStars() {
	return await trace.getTracer('nextjs-example').startActiveSpan('fetchGithubStars', async (span) => {
		try {
			return await getValue()
		} finally {
			span.end()
		}
	})
}
